select round(count(distinct t1.player_id) / (select count(distinct t3.player_id) from Activity as t3), 2) as fraction
from Activity as t1
where (t1.player_id, date(t1.event_date, '-1 day')) in (
  select t2.player_id, min(t2.event_date) from Activity as t2 group by t2.player_id
);

